'use client';

import {
  Carousel as CarouselPrimitive,
  useCarousel,
  useCarouselContext,
} from '@ark-ui/react/carousel';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef } from 'react';
import { forwardRef } from 'react';
import { ChevronLeftIcon, ChevronRightIcon } from '@/lib/moduix/icons/ui';
import styles from './Carousel.module.css';

const Carousel = forwardRef<
  ComponentRef<typeof CarouselPrimitive.Root>,
  ComponentProps<typeof CarouselPrimitive.Root>
>(function Carousel({ className, ...props }, ref) {
  return (
    <CarouselPrimitive.Root
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="carousel-root"
    />
  );
});

const CarouselRootProvider = forwardRef<
  ComponentRef<typeof CarouselPrimitive.RootProvider>,
  ComponentProps<typeof CarouselPrimitive.RootProvider>
>(function CarouselRootProvider({ className, ...props }, ref) {
  return (
    <CarouselPrimitive.RootProvider
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="carousel-root-provider"
    />
  );
});

const CarouselControl = forwardRef<
  ComponentRef<typeof CarouselPrimitive.Control>,
  ComponentProps<typeof CarouselPrimitive.Control>
>(function CarouselControl({ className, ...props }, ref) {
  return (
    <CarouselPrimitive.Control
      ref={ref}
      className={clsx(styles.control, className)}
      {...props}
      data-slot="carousel-control"
    />
  );
});

const CarouselItemGroup = forwardRef<
  ComponentRef<typeof CarouselPrimitive.ItemGroup>,
  ComponentProps<typeof CarouselPrimitive.ItemGroup>
>(function CarouselItemGroup({ className, ...props }, ref) {
  return (
    <CarouselPrimitive.ItemGroup
      ref={ref}
      className={clsx(styles.itemGroup, className)}
      {...props}
      data-slot="carousel-item-group"
    />
  );
});

const CarouselItem = forwardRef<
  ComponentRef<typeof CarouselPrimitive.Item>,
  ComponentProps<typeof CarouselPrimitive.Item>
>(function CarouselItem({ className, ...props }, ref) {
  return (
    <CarouselPrimitive.Item
      ref={ref}
      className={clsx(styles.item, className)}
      {...props}
      data-slot="carousel-item"
    />
  );
});

const CarouselPrevTrigger = forwardRef<
  ComponentRef<typeof CarouselPrimitive.PrevTrigger>,
  ComponentProps<typeof CarouselPrimitive.PrevTrigger>
>(function CarouselPrevTrigger({ className, children, ...props }, ref) {
  return (
    <CarouselPrimitive.PrevTrigger
      ref={ref}
      className={clsx(styles.trigger, className)}
      {...props}
      data-slot="carousel-prev-trigger"
    >
      {children ?? <ChevronLeftIcon className={styles.icon} />}
    </CarouselPrimitive.PrevTrigger>
  );
});

const CarouselNextTrigger = forwardRef<
  ComponentRef<typeof CarouselPrimitive.NextTrigger>,
  ComponentProps<typeof CarouselPrimitive.NextTrigger>
>(function CarouselNextTrigger({ className, children, ...props }, ref) {
  return (
    <CarouselPrimitive.NextTrigger
      ref={ref}
      className={clsx(styles.trigger, className)}
      {...props}
      data-slot="carousel-next-trigger"
    >
      {children ?? <ChevronRightIcon className={styles.icon} />}
    </CarouselPrimitive.NextTrigger>
  );
});

const CarouselIndicatorGroup = forwardRef<
  ComponentRef<typeof CarouselPrimitive.IndicatorGroup>,
  ComponentProps<typeof CarouselPrimitive.IndicatorGroup>
>(function CarouselIndicatorGroup({ className, ...props }, ref) {
  return (
    <CarouselPrimitive.IndicatorGroup
      ref={ref}
      className={clsx(styles.indicatorGroup, className)}
      {...props}
      data-slot="carousel-indicator-group"
    />
  );
});

const CarouselIndicator = forwardRef<
  ComponentRef<typeof CarouselPrimitive.Indicator>,
  ComponentProps<typeof CarouselPrimitive.Indicator>
>(function CarouselIndicator({ className, ...props }, ref) {
  return (
    <CarouselPrimitive.Indicator
      ref={ref}
      className={clsx(styles.indicator, className)}
      {...props}
      data-slot="carousel-indicator"
    />
  );
});

const CarouselIndicators = forwardRef<
  ComponentRef<typeof CarouselPrimitive.IndicatorGroup>,
  Omit<ComponentProps<typeof CarouselPrimitive.IndicatorGroup>, 'asChild' | 'children'> & {
    indicatorClassName?: string;
  }
>(function CarouselIndicators({ className, indicatorClassName, ...props }, ref) {
  return (
    <CarouselPrimitive.Context>
      {(api) => (
        <CarouselIndicatorGroup ref={ref} className={className} {...props}>
          {api.pageSnapPoints.map((_, index) => (
            <CarouselIndicator key={index} index={index} className={indicatorClassName} />
          ))}
        </CarouselIndicatorGroup>
      )}
    </CarouselPrimitive.Context>
  );
});

const CarouselAutoplayTrigger = forwardRef<
  ComponentRef<typeof CarouselPrimitive.AutoplayTrigger>,
  ComponentProps<typeof CarouselPrimitive.AutoplayTrigger>
>(function CarouselAutoplayTrigger({ className, ...props }, ref) {
  return (
    <CarouselPrimitive.AutoplayTrigger
      ref={ref}
      className={clsx(styles.trigger, styles.autoplayTrigger, className)}
      {...props}
      data-slot="carousel-autoplay-trigger"
    />
  );
});

const CarouselAutoplayIndicator = forwardRef<
  ComponentRef<typeof CarouselPrimitive.AutoplayIndicator>,
  ComponentProps<typeof CarouselPrimitive.AutoplayIndicator>
>(function CarouselAutoplayIndicator({ className, ...props }, ref) {
  return (
    <CarouselPrimitive.AutoplayIndicator
      ref={ref}
      className={clsx(styles.autoplayIndicator, className)}
      {...props}
      data-slot="carousel-autoplay-indicator"
    />
  );
});

const CarouselProgressText = forwardRef<
  ComponentRef<typeof CarouselPrimitive.ProgressText>,
  ComponentProps<typeof CarouselPrimitive.ProgressText>
>(function CarouselProgressText({ className, ...props }, ref) {
  return (
    <CarouselPrimitive.ProgressText
      ref={ref}
      className={clsx(styles.progressText, className)}
      {...props}
      data-slot="carousel-progress-text"
    />
  );
});

const CarouselContext = CarouselPrimitive.Context;

export {
  Carousel,
  CarouselAutoplayIndicator,
  CarouselAutoplayTrigger,
  CarouselContext,
  CarouselControl,
  CarouselIndicator,
  CarouselIndicatorGroup,
  CarouselIndicators,
  CarouselItem,
  CarouselItemGroup,
  CarouselNextTrigger,
  CarouselPrevTrigger,
  CarouselProgressText,
  CarouselRootProvider,
  useCarousel,
  useCarouselContext,
};

@layer moduix.components {
  .root {
    display: flex;
    flex-direction: column;
    gap: var(--moduix-carousel-gap, var(--moduix-spacing-3));
    min-width: 0;
    width: 100%;
  }

  .root[data-orientation='vertical'] {
    flex-direction: row;
    height: var(--moduix-carousel-height, 24rem);
  }

  .control {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: var(--moduix-carousel-gap, var(--moduix-spacing-3));
    min-width: 0;
  }

  .control[data-orientation='vertical'] {
    flex-direction: column;
    justify-content: space-between;
  }

  /* Ark sets display, overflow, scroll snapping, and scrollbar hiding inline. */
  .itemGroup {
    flex: 1 1 auto;
    min-width: 0;
    min-height: 0;
    border-radius: var(--moduix-radius-xl);
    outline: 0;

    &:focus-visible {
      outline: var(--moduix-focus-ring-inset-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-focus-ring-inset-offset);
    }

    &[data-dragging] {
      cursor: grabbing;
      user-select: none;
    }
  }

  .itemGroup[data-orientation='vertical'] {
    height: 100%;
    overscroll-behavior-y: contain;
  }

  .item {
    min-width: 0;
    min-height: 0;
  }

  .trigger {
    display: inline-flex;
    flex: 0 0 auto;
    align-items: center;
    justify-content: center;
    width: var(--moduix-carousel-control-size, var(--moduix-size-md));
    height: var(--moduix-carousel-control-size, var(--moduix-size-md));
    border: var(--moduix-border-width-sm) solid
      var(--moduix-carousel-control-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-radius-full);
    background-color: var(--moduix-carousel-control-bg, var(--moduix-color-card));
    box-shadow: var(--moduix-shadow-sm);
    color: var(--moduix-carousel-control-color, var(--moduix-color-foreground));
    cursor: pointer;
    transition:
      background-color var(--moduix-transition-fast),
      color var(--moduix-transition-fast);

    & svg {
      width: var(--moduix-spacing-4);
      height: var(--moduix-spacing-4);
    }

    @media (hover: hover) {
      &:not(:disabled, [data-disabled]):hover {
        background-color: var(--moduix-color-accent);
        color: var(--moduix-color-accent-foreground);
      }
    }

    &[data-pressed] {
      background-color: var(--moduix-color-accent);
      color: var(--moduix-color-accent-foreground);
    }

    &:focus-visible {
      outline: var(--moduix-focus-ring-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-focus-ring-offset);
    }

    &:is(:disabled, [data-disabled]) {
      cursor: not-allowed;
      opacity: var(--moduix-opacity-disabled);
    }
  }

  /* The autoplay trigger usually holds a text label, so it grows with its content. */
  .autoplayTrigger {
    width: auto;
    min-width: var(--moduix-carousel-control-size, var(--moduix-size-md));
    padding-inline: var(--moduix-spacing-2);
  }

  /* Default chevrons point along the paging axis. */
  .trigger[data-orientation='vertical'] > .icon {
    rotate: 90deg;
  }

  .root[dir='rtl'] .trigger[data-orientation='horizontal'] > .icon {
    rotate: 180deg;
  }

  .indicatorGroup {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: var(--moduix-spacing-2);
  }

  .indicatorGroup[data-orientation='vertical'] {
    flex-direction: column;
  }

  .indicator {
    width: var(--moduix-carousel-indicator-size, var(--moduix-spacing-2));
    height: var(--moduix-carousel-indicator-size, var(--moduix-spacing-2));
    padding: 0;
    border: 0;
    border-radius: var(--moduix-radius-full);
    background-color: var(
      --moduix-carousel-indicator-bg,
      color-mix(in oklab, var(--moduix-color-muted-foreground) 50%, transparent)
    );
    cursor: pointer;
    transition:
      width var(--moduix-transition-fast),
      height var(--moduix-transition-fast),
      background-color var(--moduix-transition-fast);

    @media (hover: hover) {
      &:not(:disabled, [data-disabled], [data-readonly], [data-current]):hover {
        background-color: var(--moduix-color-muted-foreground);
      }
    }

    &:focus-visible {
      outline: var(--moduix-focus-ring-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-focus-ring-offset);
    }

    &[data-current] {
      width: calc(var(--moduix-carousel-indicator-size, var(--moduix-spacing-2)) * 3);
      background-color: var(--moduix-carousel-indicator-bg-current, var(--moduix-color-primary));
    }

    &[data-orientation='vertical'][data-current] {
      width: var(--moduix-carousel-indicator-size, var(--moduix-spacing-2));
      height: calc(var(--moduix-carousel-indicator-size, var(--moduix-spacing-2)) * 3);
    }

    &:is(:disabled, [data-disabled], [data-readonly]) {
      cursor: not-allowed;
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .autoplayIndicator {
    font-size: var(--moduix-text-xs);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-xs);
  }

  /* Keeps "current / total" in reading order inside RTL carousels. */
  .progressText {
    color: var(--moduix-color-muted-foreground);
    direction: ltr;
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
    font-variant-numeric: tabular-nums;
    unicode-bidi: isolate;
  }

  @media (prefers-reduced-motion: reduce) {
    .trigger,
    .indicator {
      transition: none;
    }
  }

  @media (forced-colors: active) {
    .indicator {
      background-color: ButtonText;
    }

    .indicator[data-current] {
      background-color: Highlight;
    }
  }
}
